import { Vec2 } from "./";

export class Mat2 {
	// Fields are `declare`d instead of parameter properties so no class fields
	// are emitted (see the note in `Vec2`).
	/** Column 0 of the matrix (the `x` axis). */
	declare xAxis: Vec2;
	/** Column 1 of the matrix (the `y` axis). */
	declare yAxis: Vec2;

	constructor(xAxis: Vec2, yAxis: Vec2) {
		this.xAxis = xAxis;
		this.yAxis = yAxis;
	}

	/**
	 * Creates a new `Mat2` from multiple values.
	 */
	static new(m00: number, m01: number, m10: number, m11: number): Mat2 {
		return new Mat2(new Vec2(m00, m01), new Vec2(m10, m11));
	}

	/** All zeroes. (0, 0..) */
	static get ZERO() {
		return new Mat2(new Vec2(0, 0), new Vec2(0, 0));
	}

	/** All `Identity`, where all diagonal elements are `1`, and all off-diagonal elements are `0`. */
	static get IDENTITY() {
		return new Mat2(new Vec2(1, 0), new Vec2(0, 1));
	}

	/** All `NaN`. (NaN, NaN..) */
	static get NAN() {
		return new Mat2(
			new Vec2(Number.NaN, Number.NaN),
			new Vec2(Number.NaN, Number.NaN),
		);
	}

	/**
	 * Creates a 2x2 matrix from four column vectors.
	 */
	static fromCols(xAxis: Vec2, yAxis: Vec2): Mat2 {
		return new Mat2(xAxis, yAxis);
	}

	/**
	 * Creates a 2x2 matrix from four column vectors.
	 */
	static fromColsArray(m: number[]): Mat2 {
		return Mat2.new(m[0], m[1], m[2], m[3]);
	}

	/**
	 * Creates an array storing data in column major order.
	 */
	toColsArray(): number[] {
		return [this.xAxis.x, this.xAxis.y, this.yAxis.x, this.yAxis.y];
	}
}
